  .sky { position: fixed; inset: 0; z-index: 0; transition: opacity .8s ease; }
  #skyDay { background: linear-gradient(165deg, #cfe9ff 0%, #8ec6f5 45%, #4a90d9 100%); }
  #skyNight { background: linear-gradient(180deg, #04091a 0%, #0d1b36 55%, #1c3a68 100%); opacity: 0; }
  body.night #skyDay { opacity: 0; }
  body.night #skyNight { opacity: 1; }

  .sun {
    position: absolute; top: 7%; right: 8%; font-size: 64px;
    animation: bob 5s ease-in-out infinite;
  }
  @keyframes bob { 0%,100% { transform: translateY(0); } 50% { transform: translateY(12px); } }
  .cloud {
    position: absolute; height: 34px; background: rgba(255,255,255,.85);
    border-radius: 40px; animation: drift linear infinite;
  }
  .cloud::before, .cloud::after { content: ""; position: absolute; background: inherit; border-radius: 50%; }
  .cloud::before { width: 54px; height: 54px; top: -25px; left: 16px; }
  .cloud::after  { width: 38px; height: 38px; top: -15px; right: 16px; }
  @keyframes drift { from { transform: translateX(-25vw); } to { transform: translateX(125vw); } }
  .c1 { top: 12%; width: 120px; animation-duration: 75s; }
  .c2 { top: 30%; width: 90px;  animation-duration: 100s; animation-delay: -40s; opacity: .8; }
  .c3 { top: 70%; width: 70px;  animation-duration: 130s; animation-delay: -70s; opacity: .55; }

  .moon {
    position: absolute; top: 8%; right: 9%; width: 58px; height: 58px; border-radius: 50%;
    background: radial-gradient(circle at 35% 35%, #f8f4e2, #ddd5b4);
    box-shadow: 0 0 42px rgba(244, 240, 220, .45), inset -12px -10px 0 rgba(120, 112, 78, .25);
  }
  .star {
    position: absolute; background: #fff; border-radius: 50%;
    animation: twinkle var(--tw, 3s) ease-in-out var(--td, 0s) infinite;
  }
  @keyframes twinkle {
    0%, 100% { opacity: var(--o, .8); }
    50% { opacity: calc(var(--o, .8) * .2); }
  }
