from html.parser import HTMLParser

class Checker(HTMLParser):
    VOID = {'meta','br','img','hr','input','link','area','base','col','embed','source','track','wbr'}
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in self.VOID:
            self.stack.append((tag, self.getpos()))
    def handle_endtag(self, tag):
        if not self.stack:
            self.errors.append(f"stray </{tag}> at {self.getpos()}")
            return
        open_tag, pos = self.stack.pop()
        if open_tag != tag:
            self.errors.append(f"mismatch: <{open_tag}> at {pos} closed by </{tag}> at {self.getpos()}")

c = Checker()
c.feed(open('index.html', encoding='utf-8').read())
if c.stack:
    c.errors.append(f"unclosed: {c.stack}")
print("TAG ERRORS:", c.errors if c.errors else "none")
