{"content": "<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>البنية الداخلية للأرض · طبقات القشرة والوشاح والنواة</title>
<style>
  :root {
    --ink: #f3e9d7;
    --muted: #c4ad8b;
    --card: rgba(32, 22, 12, .93);
    --line: rgba(232, 169, 60, .22);
    --accent: #e8a93c;
    --accent-soft: rgba(232, 169, 60, .13);
    --crust: #8a5a3b;
    --mantle: #d2691e;
    --outer: #f0a928;
    --inner: #ffd75e;
    --shadow: rgba(0, 0, 0, .5);
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { height: 100%; overflow: hidden; }
  body {
    font-family: "Segoe UI", Tahoma, "Noto Sans Arabic", "Noto Kufi Arabic", "Geeza Pro", Arial, sans-serif;
    color: var(--ink);
    background: linear-gradient(180deg, #150e07 0%, #241708 55%, #33200c 100%);
  }

  /* ---------- progress ---------- */
  #progress {
    position: fixed; top: 0; right: 0; left: auto; height: 4px; width: 0;
    background: var(--accent); border-radius: 0 0 2px 2px;
    transition: width .4s ease; z-index: 20;
  }

  /* ---------- decorative background ---------- */
  .bg-glow {
    position: fixed; inset: 0; z-index: 0; pointer-events: none;
    background:
      radial-gradient(ellipse 70% 45% at 50% 108%, rgba(255, 132, 26, .22), transparent 70%),
      radial-gradient(ellipse 50% 30% at 85% -10%, rgba(120, 80, 40, .25), transparent 70%);
  }
  .strata {
    position: fixed; left: 0; right: 0; bottom: 0; height: 150px; z-index: 0; pointer-events: none; opacity: .3;
    background: repeating-linear-gradient(180deg, #4a2c14 0 16px, #2e1c0c 16px 30px, #55341a 30px 52px, #22150a 52px 72px);
    -webkit-mask-image: linear-gradient(180deg, transparent, #000);
    mask-image: linear-gradient(180deg, transparent, #000);
  }

  /* ---------- deck / slides ---------- */
  #deck { position: relative; height: 100%; }
  .slide {
    position: absolute; inset: 0; z-index: 1;
    display: flex; align-items: center; justify-content: center;
    padding: 44px 24px 96px;
    opacity: 0; visibility: hidden; transform: translateX(-48px);
    transition: opacity .45s ease, transform .45s ease, visibility .45s;
    overflow-y: auto;
  }
  .slide.active { opacity: 1; visibility: visible; transform: none; }

  .card {
    width: 100%; max-width: 1180px;
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 20px;
    box-shadow: 0 24px 60px var(--shadow);
    padding: 28px 34px 34px;
  }
  .card h2 {
    font-size: 1.5rem; font-weight: 800; margin-bottom: 12px;
    padding-bottom: 12px; border-bottom: 2px solid var(--line);
  }
  .card h2 .bar { display: inline-block; width: 34px; height: 5px; border-radius: 3px; background: var(--accent); margin-left: 10px; vertical-align: 4px; }
  .card h3 { font-size: 1.08rem; font-weight: 800; margin: 18px 0 8px; color: var(--accent); }
  .card p { font-size: .97rem; line-height: 1.9; margin: 10px 0; }

  /* ---------- title slide ---------- */
  .title-card { text-align: center; max-width: 780px; padding: 40px 36px; }
  .title-card .over { font-size: 1rem; color: var(--muted); margin-bottom: 14px; }
  .title-card h1 { font-size: clamp(2.2rem, 5.5vw, 3.4rem); font-weight: 800; color: var(--accent); letter-spacing: -.5px; }
  .title-card .rule { width: 70px; height: 4px; border-radius: 2px; background: var(--accent); margin: 24px auto; opacity: .5; }
  .title-card .sub { font-size: 1.08rem; line-height: 1.8; color: var(--ink); }
  .title-card .hint2 { margin-top: 18px; font-size: .85rem; color: var(--muted); }
  .mini-earth { width: 260px; max-width: 70%; margin: 0 auto 18px; }

  /* ---------- two columns ---------- */
  .cols { display: grid; grid-template-columns: 1fr 1fr; gap: 0; }
  .col { padding: 6px 30px; min-width: 0; }
  .col:first-child { padding-right: 4px; }
  .col:last-child  { padding-left: 4px; border-right: 1px solid var(--line); }

  .fig-wrap { display: flex; flex-direction: column; justify-content: center; align-items: center; }
  .earth-svg { width: 100%; max-width: 400px; height: auto; }
  .earth-svg .lyr { cursor: pointer; transition: filter .25s ease, opacity .4s ease; }
  .earth-svg .lyr:hover { filter: brightness(1.25); }
  .earth-svg .lyr.dim { opacity: .22; filter: saturate(.5); }
  .earth-svg text { font-family: inherit; }
  .scale-note { font-size: .78rem; color: var(--muted); text-align: center; margin-top: 10px; }

  /* ---------- chips (overview) ---------- */
  .chips { display: flex; flex-direction: column; gap: 10px; margin: 16px 0; }
  .chip {
    display: flex; align-items: center; gap: 12px; text-align: right; cursor: pointer;
    background: var(--accent-soft); border: 1px solid var(--line); border-radius: 12px;
    padding: 12px 16px; color: var(--ink); font-family: inherit;
    transition: background .25s ease, transform .15s ease;
  }
  .chip:hover { background: rgba(232, 169, 60, .24); transform: translateX(-4px); }
  .chip .ico { font-size: 1.6rem; }
  .chip-txt { display: flex; flex-direction: column; }
  .chip-txt b { font-size: 1.04rem; }
  .chip-txt small { color: var(--muted); font-size: .8rem; margin-top: 2px; }

  /* ---------- stat chips ---------- */
  .stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin: 16px 0; }
  .stat { background: var(--accent-soft); border: 1px solid var(--line); border-radius: 12px; padding: 10px 14px; }
  .stat .s-label { font-size: .78rem; color: var(--muted); display: block; margin-bottom: 3px; }
  .stat .s-val { font-size: .98rem; font-weight: 800; }
  .fact {
    margin-top: 14px; padding: 12px 16px; border-radius: 12px;
    background: var(--accent-soft); border-right: 4px solid var(--accent);
    font-size: .92rem; line-height: 1.8;
  }

  /* ---------- journey ---------- */
  .drill-svg { width: 100%; max-width: 300px; height: auto; display: block; margin: 0 auto; }
  .drill-svg .band { transition: filter .3s ease; }
  .drill-svg .band.here { filter: brightness(1.28); stroke: #ffe9a8; stroke-width: 2; }
  .readouts { display: flex; flex-direction: column; gap: 12px; margin: 16px 0 8px; }
  .ro {
    display: flex; justify-content: space-between; align-items: center; gap: 10px;
    background: var(--accent-soft); border: 1px solid var(--line); border-radius: 12px; padding: 12px 16px;
  }
  .ro-label { color: var(--muted); font-size: .92rem; }
  .ro-val { font-weight: 800; font-size: 1.3rem; direction: ltr; unicode-bidi: isolate; }
  .ro-bar { height: 10px; border-radius: 999px; background: rgba(255, 255, 255, .08); overflow: hidden; margin: 6px 0 18px; }
  #roBarFill {
    height: 100%; width: 0; border-radius: 999px;
