<div id="controls" role="navigation" aria-label="التنقل بين الشرائح">
  <button id="prev" aria-label="الشريحة السابقة">→</button>
  <div class="dots" id="dots"></div>
  <button id="next" aria-label="الشريحة التالية">←</button>
  <span id="counter" aria-live="polite"></span>
</div>

<script>
(function () {
  "use strict";

  /* ================= شريط الشرائح ================= */
  var slides = Array.prototype.slice.call(document.querySelectorAll(".slide"));
  var dotsWrap = document.getElementById("dots");
  var prevBtn = document.getElementById("prev");
  var nextBtn = document.getElementById("next");
  var counter = document.getElementById("counter");
  var progress = document.getElementById("progress");
  var current = 0;

  slides.forEach(function (s, i) {
    var d = document.createElement("button");
    d.type = "button";
    d.setAttribute("aria-label", "الانتقال إلى الشريحة " + (i + 1) + ": " + s.dataset.label);
    d.addEventListener("click", function () { goTo(i); });
    dotsWrap.appendChild(d);
  });
  var dots = Array.prototype.slice.call(dotsWrap.children);

  function goTo(i) {
    current = Math.max(0, Math.min(slides.length - 1, i));
    slides.forEach(function (s, idx) { s.classList.toggle("active", idx === current); });
    dots.forEach(function (d, idx) { d.classList.toggle("active", idx === current); });
    prevBtn.disabled = current === 0;
    nextBtn.disabled = current === slides.length - 1;
    counter.textContent = (current + 1) + " / " + slides.length;
    progress.style.width = ((current + 1) / slides.length * 100) + "%";
    slides[current].scrollTop = 0;
  }

  prevBtn.addEventListener("click", function () { goTo(current - 1); });
  nextBtn.addEventListener("click", function () { goTo(current + 1); });

  document.addEventListener("keydown", function (e) {
