  function earthSVG(opts) {
    var hl = opts.highlight || null;
    var interactive = !!opts.interactive;
    function dimmed(name) {
      if (!hl) return false;
      if (hl === "core") return name !== "outer-core" && name !== "inner-core";
      return hl !== name;
    }
    function layer(name, r, fill) {
      var cls = "lyr lyr-" + name + (dimmed(name) ? " dim" : "");
      var go = interactive ? ' data-goto="' + (name === "crust" ? 2 : name === "mantle" ? 3 : 4) + '"' : "";
      var tt = interactive ? "<title>" + AR_NAMES[name] + "</title>" : "";
      return '<circle class="' + cls + '" cx="210" cy="210" r="' + r + '" fill="' + fill + '"' + go + ">" + tt + "</circle>";
    }
    var s = '<svg class="earth-svg' + (interactive ? " interactive" : "") + '" viewBox="0 0 420 420" role="img" aria-label="مقطع عرضي لباطن الأرض">';
    s += '<circle cx="210" cy="210" r="205" fill="url(#gGlow)" opacity=".5"/>';
    s += layer("crust", 195, "url(#gCrust)");
    s += layer("mantle", 184, "url(#gMantle)");
    s += layer("outer-core", 106, "url(#gOuter)");
