    s += '<circle cx="210" cy="210" r="184" fill="none" stroke="rgba(0,0,0,.25)" stroke-width="1.5"/>';
    s += '<circle cx="210" cy="210" r="106" fill="none" stroke="rgba(0,0,0,.25)" stroke-width="1.5"/>';
    s += '<circle cx="210" cy="210" r="38" fill="none" stroke="rgba(0,0,0,.2)" stroke-width="1.2"/>';
    if (interactive) {
      LABELS.forEach(function (L) {
        s += '<line x1="' + L.x + '" y1="' + (L.y + 8) + '" x2="' + L.px + '" y2="' + L.py + '" stroke="rgba(243,233,215,.65)" stroke-width="1.2"/>';
        s += '<circle cx="' + L.px + '" cy="' + L.py + '" r="3.2" fill="#fff3c4"/>';
        s += '<text x="' + L.x + '" y="' + L.y + '" text-anchor="middle" font-size="16" fill="#f5e9d0">' + L.t + "</text>";
      });
    }
    s += "</svg>";
    return s;
  }

  document.getElementById("fig-title").innerHTML = earthSVG({});
  document.getElementById("fig-overview").innerHTML = earthSVG({ interactive: true });
  document.getElementById("fig-crust").innerHTML = earthSVG({ highlight: "crust" });
  document.getElementById("fig-mantle").innerHTML = earthSVG({ highlight: "mantle" });
  document.getElementById("fig-core").innerHTML = earthSVG({ highlight: "core" });

  // النقر على الطبقات في الخريطة التفاعلية
  document.querySelectorAll(".earth-svg.interactive .lyr").forEach(function (c) {
    c.addEventListener("click", function () { goTo(parseInt(c.dataset.goto, 10)); });
  });
  document.querySelectorAll(".chip[data-goto]").forEach(function (c) {
    c.addEventListener("click", function () { goTo(parseInt(c.dataset.goto, 10)); });
  });

  /* ================= رحلة إلى المركز ================= */
  var drillLine = document.getElementById("drillLine");
  var drillRing = document.getElementById("drillRing");
  var drillDot = document.getElementById("drillDot");
  var roDepth = document.getElementById("roDepth");
  var roTemp = document.getElementById("roTemp");
  var roLayer = document.getElementById("roLayer");
  var roBarFill = document.getElementById("roBarFill");
  var jStart = document.getElementById("jStart");
  var jReset = document.getElementById("jReset");

  var D = 6371, DUR = 14000;
  var J = { running: false, done: false, t: 0, last: null, raf: null };

  // خريطة العمق → موقع الرسم (مطابق للأشرطة، القشرة مُكبَّرة)
  function depthToY(d) {
    if (d <= 70) return 20 + (d / 70) * 14;
    if (d <= 2890) return 34 + ((d - 70) / 2820) * 205;
    if (d <= 5150) return 239 + ((d - 2890) / 2260) * 165;
    return 404 + ((d - 5150) / 1221) * 88;
  }

  var TP = [[0, 15], [70, 400], [400, 1000], [2890, 3800], [5150, 5000], [6371, 5500]];
  function tempAt(d) {
    for (var i = 1; i < TP.length; i++) {
      if (d <= TP[i][0]) {
        var a = TP[i - 1], b = TP[i];
        return a[1] + (b[1] - a[1]) * (d - a[0]) / (b[0] - a[0]);
      }
    }
    return 5500;
  }

  function layerAt(d) {
    return d < 70 ? "القشرة" : d < 2890 ? "الوشاح" : d < 5150 ? "النواة الخارجية" : "النواة الداخلية";
  }

  function fmt(n) { return Math.round(n).toLocaleString("en-US"); }

  function setDepth(d) {
    var y = depthToY(d);
    drillLine.setAttribute("y2", y);
    drillRing.setAttribute("cy", y);
    drillDot.setAttribute("cy", y);
    roDepth.textContent = fmt(d) + " كم";
    roTemp.textContent = fmt(tempAt(d)) + "°م";
    roLayer.textContent = layerAt(d);
    roBarFill.style.width = (tempAt(d) / 5500 * 100) + "%";
    var name = d < 70 ? "b-crust" : d < 2890 ? "b-mantle" : d < 5150 ? "b-outer" : "b-inner";
    ["b-crust", "b-mantle", "b-outer", "b-inner"].forEach(function (id) {
      document.getElementById(id).classList.toggle("here", id === name);
    });
  }

  function tick(now) {
    if (!J.running) return;
    if (J.last === null) J.last = now;
    J.t += now - J.last;
    J.last = now;
    var p = Math.min(1, J.t / DUR);
    setDepth(D * p);
    if (p < 1) {
      J.raf = requestAnimationFrame(tick);
    } else {
      J.running = false;
      J.done = true;
      jStart.textContent = "↺ إعادة الرحلة";
    }
  }

  function startJourney() {
    if (J.running) {
      J.running = false;
      if (J.raf) cancelAnimationFrame(J.raf);
      jStart.textContent = "▶ متابعة";
      return;
    }
    if (J.done) { J.t = 0; J.done = false; setDepth(0); }
    J.running = true;
    J.last = null;
    jStart.textContent = "⏸ إيقاف مؤقت";
    J.raf = requestAnimationFrame(tick);
  }

  function resetJourney() {
    J.running = false; J.done = false; J.t = 0; J.last = null;
    if (J.raf) cancelAnimationFrame(J.raf);
    setDepth(0);
    jStart.textContent = "🚀 ابدأ الرحلة";
  }

  jStart.addEventListener("click", startJourney);
  jReset.addEventListener("click", resetJourney);
  setDepth(0);

  goTo(0);
})();
</script>
</body>
