        if c == '"': state='string'; i += 1; continue
        if c == "'":
            j = i+1
            while j < n and src[j] != "'":
                if src[j] == '\\': j += 1
                j += 1
            if j >= n: return err("unterminated char literal")
            i = j+1; continue
        if c in '([{': stack.append((c,line,False)); i += 1; continue
        if c in ')]}':
            if not stack: return err(f"unbalanced '{c}'")
            oc, ol, tpl = stack.pop()
            if oc != pairs[c]: return err(f"'{c}' != '{oc}' from line {ol}")
            if tpl: state = 'string'
            i += 1; continue
        i += 1
    if stack: return err(f"unclosed '{stack[-1][0]}' line {stack[-1][1]}")
    if state != 'code': return err(f"ends in {state}")
    print(f"{path}: OK — valid structure")
